import{_ as t,a,c as n,j as i}from"./chunks/framework.DVzkjf-b.js";const u=JSON.parse('{"title":"Why UAP Records Are an Unusually Demanding AI Research Testbed","description":"A case for using UAP archives to test provenance, entity resolution, correlated sources, changing evidence, and source-aware intelligence briefings.","frontmatter":{"title":"Why UAP Records Are an Unusually Demanding AI Research Testbed","description":"A case for using UAP archives to test provenance, entity resolution, correlated sources, changing evidence, and source-aware intelligence briefings."},"headers":[],"relativePath":"research/systems/uap-research-testbed.md","filePath":"research/systems/uap-research-testbed.md"}'),s={name:"research/systems/uap-research-testbed.md"};function r(o,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="why-uap-records-are-an-unusually-demanding-research-testbed" tabindex="-1">Why UAP Records Are an Unusually Demanding Research Testbed <a class="header-anchor" href="#why-uap-records-are-an-unusually-demanding-research-testbed" aria-label="Permalink to &quot;Why UAP Records Are an Unusually Demanding Research Testbed&quot;">​</a></h1><p><em>Research-methods position · November 2026</em></p><p>My proposed UAP corpus is not an attempt to prove any predetermined explanation of unidentified phenomena. It is a way to examine whether AI can <strong>organize uncertain, contradictory and imperfect evidence without erasing the distinction between observation, testimony and interpretation</strong>.</p><p>That makes UAP a strong stress test for an evidence-governed knowledge system. It does <strong>not</strong> make it a sufficient scientific benchmark on its own.</p><h2 id="why-this-domain-is-useful" tabindex="-1">Why this domain is useful <a class="header-anchor" href="#why-this-domain-is-useful" aria-label="Permalink to &quot;Why this domain is useful&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Difficult property</th><th>Research capability being tested</th></tr></thead><tbody><tr><td>Scans, text, audio, video, testimony and incomplete sensor records</td><td>Multimodal extraction and precise passage/timecode citations</td></tr><tr><td>Historical accounts and later reinterpretations</td><td>Temporal provenance and versioned assessments</td></tr><tr><td>People and organizations with multiple aliases and roles</td><td>Entity linking and source-specific disambiguation</td></tr><tr><td>Several publications repeating one original witness</td><td>Detecting correlated sources rather than false corroboration</td></tr><tr><td>Conflicting narratives, institutional positions and skeptical alternatives</td><td>Maintaining attributed propositions and competing hypotheses</td></tr><tr><td>Unknown causes or missing primary measurements</td><td>Explicit uncertainty and evidence gaps rather than fabricated certainty</td></tr><tr><td>Original records, transcriptions, OCR, summaries, and generated derivatives</td><td>Recording transformations without treating derivatives as independent witnesses</td></tr><tr><td>New official releases over time</td><td>Incremental graph updates and explicit explanations of assessment changes</td></tr><tr><td>Restricted, redacted or copyrighted material</td><td>Rights-aware acquisition, indexing and presentation</td></tr><tr><td>Many possible questions and audiences</td><td>Generating different grounded artifacts from one shared evidence base</td></tr></tbody></table><p><a href="https://www.nasa.gov/wp-content/uploads/2023/09/uap-independent-study-team-final-report-0.pdf" target="_blank" rel="noreferrer">NASA&#39;s 2023 independent UAP study</a> explicitly highlights missing calibration data and metadata for many observations. The lack of data is itself a subject of the proposed investigation, not a reason to invent definitive answers.</p><h2 id="an-official-evolving-records-source" tabindex="-1">An official, evolving records source <a class="header-anchor" href="#an-official-evolving-records-source" aria-label="Permalink to &quot;An official, evolving records source&quot;">​</a></h2><p>The <a href="https://www.archives.gov/research/topics/uaps/rg-615" target="_blank" rel="noreferrer">National Archives&#39; Record Group 615</a> contains UAP records received from federal agencies pursuant to the FY2024 National Defense Authorization Act. The National Archives says it will update the collection as new records arrive.</p><p>This establishes official custody and a continuing acquisition pathway. <strong>It does not establish the truth of each statement in the records</strong>, nor does a public download link automatically settle all possible reuse rights.</p><p>The evolving collection is valuable for testing whether the system notices new evidence, preserves earlier versions and explains why an assessment changed.</p><h2 id="what-the-system-is-responsible-for" tabindex="-1">What the system is responsible for <a class="header-anchor" href="#what-the-system-is-responsible-for" aria-label="Permalink to &quot;What the system is responsible for&quot;">​</a></h2><p>It should be answerable for: correctly identifying and preserving original source material; attributing each claim; distinguishing contemporaneous records from later recollections; flagging ambiguous people/events; representing evidence dependence; citing specific passages; and accurately recording why a judgment was made.</p><p>It <strong>cannot claim certainty about an event with no independently verifiable ground truth</strong>. A statement such as “A testified that B happened” is testable against the transcript. “B really happened” may not be independently testable.</p><p>A Five Ws review asks who, what, when, where, why and how. A Five Whys investigation traces the <strong>basis of the system&#39;s assessment or failure</strong>, while allowing multiple explanations and stopping at evidence gaps.</p><h2 id="the-existing-corpus-is-not-yet-acquired" tabindex="-1">The existing corpus is not yet acquired <a class="header-anchor" href="#the-existing-corpus-is-not-yet-acquired" aria-label="Permalink to &quot;The existing corpus is not yet acquired&quot;">​</a></h2><p>The November 2026 UAP corpus planning repository describes a <strong>38-item curated metadata catalog and four collection entry points</strong>, not a completed media archive. Originals, OCR/ASR derivatives and annotated claim labels have not yet been downloaded or evaluated. This is a documented development status, not a research result.</p><p>A defensible pilot would select a small rights-cleared group: a government report, hearing transcript, historical investigation, and independently authored account. Store original hashes, acquisition receipts, source spans, media timestamps, exact dates, and rights decisions. Annotators then label attributable statements, source copying, uncertainty and contradictions.</p><h2 id="why-an-additional-benchmark-is-mandatory" tabindex="-1">Why an additional benchmark is mandatory <a class="header-anchor" href="#why-an-additional-benchmark-is-mandatory" aria-label="Permalink to &quot;Why an additional benchmark is mandatory&quot;">​</a></h2><p>UAP archives are <strong>not ideal ground truth for extraordinary historical outcomes</strong>. Selection bias, incomplete instrumentation, disputed recollections, and inaccessible source material limit what can be known.</p><p>Pair UAP with an independently labeled entity-resolution and claim-attribution benchmark, plus a controlled synthetic corpus where source copying, false identities, and event truth are specified. The controlled corpus lets us calculate false positives and false negatives; the UAP sample evaluates ecological realism, provenance and navigation.</p><p>Do not train on synthetic derivatives of the same source and then treat those derivatives as independent evaluation cases.</p><h2 id="how-the-interface-should-communicate-it" tabindex="-1">How the interface should communicate it <a class="header-anchor" href="#how-the-interface-should-communicate-it" aria-label="Permalink to &quot;How the interface should communicate it&quot;">​</a></h2><p>A reader could open an executive brief, select an event, explore two different graphs (a <strong>page navigation graph</strong> and a <strong>claim/evidence graph</strong>), read a dynamically composed dossier, and inspect original passages. Wikipedia and Wikidata may help discover topics and candidate identifiers but are named <strong>external context sources</strong>, not the user interface or final authority.</p><p>The interface should answer: “What do we know?”, “Why is that assessment supported?”, “Which sources may depend on one another?”, and “What new evidence would change it?”</p><h2 id="broader-application-and-research-funding-relevance" tabindex="-1">Broader application and research funding relevance <a class="header-anchor" href="#broader-application-and-research-funding-relevance" aria-label="Permalink to &quot;Broader application and research funding relevance&quot;">​</a></h2><p>The same methods may apply to scientific literature, journalism, public archives, cybersecurity, fraud investigations, intelligence analysis and enterprise document knowledge. <a href="https://www.intelligence.gov/mission/our-values/objectivity" target="_blank" rel="noreferrer">ODNI analytic standards, ICD 203</a>, give a substantive benchmark for sourcing, uncertainty and competing explanations.</p><p>This is a case for researching <strong>trustworthy information processing</strong>, not a claim that the government has committed funding to this project or that a UAP-specific grant exists. Application opportunities are dependent on sponsor goals, eligibility and timing and must be checked separately.</p><p><a href="./">Research hub</a> · <a href="./vision-and-interface">Interface architecture</a> · <a href="./dissertation-proposal">Advisor proposal</a></p>',29)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
